26: // Request is the representation of a HTTP request made by a Collector
27: type Request struct {
28: 	// URL is the parsed URL of the HTTP request
29: 	URL *url.URL
30: 	// Headers contains the Request's HTTP headers
31: 	Headers *http.Header
32: 	// the Host header
33: 	Host string
34: 	// Ctx is a context between a Request and a Response
35: 	Ctx *Context
36: 	// Depth is the number of the parents of the request
37: 	Depth int
38: 	// Method is the HTTP method of the request
39: 	Method string
40: 	// Body is the request body which is used on POST/PUT requests
41: 	Body io.Reader
42: 	// ResponseCharacterencoding is the character encoding of the response body.
43: 	// Leave it blank to allow automatic character encoding of the response body.
44: 	// It is empty by default and it can be set in OnRequest callback.
45: 	ResponseCharacterEncoding string
46: 	// ID is the Unique identifier of the request
47: 	ID        uint32
48: 	collector *Collector
49: 	abort     bool
50: 	baseURL   *url.URL
51: 	// ProxyURL is the proxy address that handles the request
52: 	ProxyURL string
53: }
54: 
55: type serializableRequest struct {
56: 	URL     string
57: 	Method  string
58: 	Depth   int
59: 	Body    []byte
60: 	ID      uint32
61: 	Ctx     map[string]interface{}
62: 	Headers http.Header
63: 	Host    string
64: }
65: 
66: // New creates a new request with the context of the original request
67: func (r *Request) New(method, URL string, body io.Reader) (*Request, error) {
68: 	u, err := urlParser.Parse(URL)
69: 	if err != nil {
70: 		return nil, err
71: 	}
72: 	u2, err := url.Parse(u.Href(false))
73: 	if err != nil {
74: 		return nil, err
75: 	}
76: 	return &Request{
77: 		Method:    method,
78: 		URL:       u2,
79: 		Body:      body,
80: 		Ctx:       r.Ctx,
81: 		Headers:   &http.Header{},
82: 		Host:      r.Host,
83: 		ID:        r.collector.requestCount.Add(1),
84: 		collector: r.collector,
85: 	}, nil
86: }
87: 
88: // Abort cancels the HTTP request when called in an OnRequest callback
89: func (r *Request) Abort() {
90: 	r.abort = true
91: }
92: 
93: // IsAbort returns true if the request has been aborted
94: func (r *Request) IsAbort() bool {
95: 	return r.abort
96: }
