98: // AbsoluteURL returns with the resolved absolute URL of an URL chunk.
99: // AbsoluteURL returns empty string if the URL chunk is a fragment or
100: // could not be parsed
101: func (r *Request) AbsoluteURL(u string) string {
102: 	if strings.HasPrefix(u, "#") {
103: 		return ""
104: 	}
105: 	var base *url.URL
106: 	if r.baseURL != nil {
107: 		base = r.baseURL
108: 	} else {
109: 		base = r.URL
110: 	}
111: 
112: 	absURL, err := urlParser.ParseRef(base.String(), u)
113: 	if err != nil {
