168: 	newS := s
169: 	if selector != "" {
170: 		newS = newS.Find(selector)
171: 	}
172: 	if newS.Nodes == nil {
173: 		return nil
174: 	}
175: 	e := attrV.Type().Elem()
176: 	if e.Kind() != reflect.Struct {
177: 		return errors.New("Invalid slice type")
178: 	}
179: 	v := reflect.New(e)
180: 	err := UnmarshalHTML(v.Interface(), newS, nil)
181: 	if err != nil {
182: 		return err
183: 	}
184: 	attrV.Set(v)
185: 	return nil
186: }
